package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="material_inventory")
public class MaterialInventory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String name; @Column(length=2000) private String description; private int quantity; @Column(name="received_at") private LocalDate receivedAt; private String supplier; public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getName(){return name;} public void setName(String name){this.name=name;} public String getDescription(){return description;} public void setDescription(String description){this.description=description;} public int getQuantity(){return quantity;} public void setQuantity(int quantity){this.quantity=quantity;} public LocalDate getReceivedAt(){return receivedAt;} public void setReceivedAt(LocalDate receivedAt){this.receivedAt=receivedAt;} public String getSupplier(){return supplier;} public void setSupplier(String supplier){this.supplier=supplier;} }
